# 세션 A (H2 콘솔 1)
set autocommit false;
update member set money = 5000 where member_id = 'memberA';

select * from member;
# MEMBER_ID | MONEY
# memberA   | 5000      <- 바뀐 값이 보인다
# memberB   | 10000

# 세션 B (H2 콘솔 2) - 같은 시각
select * from member;
# MEMBER_ID | MONEY
# memberA   | 10000     <- 옛날 값이 보인다
# memberB   | 10000

# 세션 A
commit;

# 세션 B
select * from member;
# MEMBER_ID | MONEY
# memberA   | 5000      <- 이제 보인다

# 만약 세션 A 가 rollback 했다면
# memberA   | 10000     <- 없던 일이 된다
